package org.fribok.bookkeeping.dataformat;
import org.junit.jupiter.api.Test;import se.swedsoft.bookkeeping.data.*;import se.swedsoft.bookkeeping.data.common.*;import java.io.*;import java.math.*;import java.nio.charset.*;import java.sql.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class ProductRegisterStagingConverterTest{
 @Test void roundTripsAllProductFieldsMapsAndOrderedComponents()throws Exception{try(Connection legacy=conn("product_legacy");Connection target=conn("product_target")){schema(legacy);new SchemaMigrationRunner(Clock.fixed(Instant.EPOCH,ZoneOffset.UTC)).migrate(target,NormalizedSchemaMigrations.load());SSNewCompany company=new SSNewCompany();company.setId(1);insertCompany(legacy,company);SSNewProject project=new SSNewProject("P1","Project",null);insertScoped(legacy,"tbl_project","project","P1",project);SSNewResultUnit unit=new SSNewResultUnit("R1","Unit");insertScoped(legacy,"tbl_resultunit","resultunit","R1",unit);SSProduct product=product();try(var p=legacy.prepareStatement("INSERT INTO tbl_product (id,number,product,companyid) VALUES (?,?,?,?)")){p.setInt(1,7);p.setString(2,product.getNumber());p.setObject(3,product);p.setInt(4,1);p.executeUpdate();legacy.commit();}new AccountingCoreStagingConverter().convert(legacy,target);new AccountingDimensionsStagingConverter().convert(legacy,target);var result=new ProductRegisterStagingConverter().convert(legacy,target);assertThat(result.sourceFingerprint()).isEqualTo(result.destinationFingerprint());assertThat(result.products()).isEqualTo(1);assertThat(result.descriptions()).isEqualTo(2);assertThat(result.defaultAccounts()).isEqualTo(2);assertThat(result.components()).isEqualTo(2);assertThat(count(target,"product_component")).isEqualTo(2);}}
 @Test void rejectsTableAndObjectNumberMismatch()throws Exception{try(Connection legacy=conn("product_bad_legacy");Connection target=conn("product_bad_target")){schema(legacy);new SchemaMigrationRunner(Clock.fixed(Instant.EPOCH,ZoneOffset.UTC)).migrate(target,NormalizedSchemaMigrations.load());SSNewCompany c=new SSNewCompany();c.setId(1);insertCompany(legacy,c);new AccountingCoreStagingConverter().convert(legacy,target);SSProduct x=new SSProduct();x.setNumber("object");try(var p=legacy.prepareStatement("INSERT INTO tbl_product (id,number,product,companyid) VALUES (?,?,?,?)")){p.setInt(1,7);p.setString(2,"table");p.setObject(3,x);p.setInt(4,1);p.executeUpdate();legacy.commit();}assertThatThrownBy(()->new ProductRegisterStagingConverter().convert(legacy,target)).isInstanceOf(SQLException.class).hasMessageContaining("Product key/object mismatch");}}
 private static SSProduct product(){SSProduct p=new SSProduct();p.setNumber("ART-Å");p.setDescription("");p.setSellingPrice(new BigDecimal("12.345"));p.setTaxCode(SSTaxCode.TAXRATE_2);p.setWarehouseLocation("A1");p.setOrderpoint(-1);p.setOrdercount(5);p.setPurchasePrice(new BigDecimal("7.50"));p.setStockPrice(null);p.setUnitFreight(new BigDecimal("0.00"));p.setSupplierNr("L1");p.setSupplierProductNr("LX");p.setExpired(true);p.setStockProduct(false);p.setUnit(new SSUnit("kg","kilogram"));p.setWeight(null);p.setVolume(new BigDecimal("1.250"));p.setProjectNr("P1");p.setResultUnitNr("R1");p.setDescription(Locale.forLanguageTag("sv-SE"),"Svensk");p.setDescription(Locale.forLanguageTag("en-US"),"");p.setDefaultAccount(SSDefaultAccount.Sales,3001);p.setDefaultAccount(SSDefaultAccount.Purchases,(Integer)null);SSProductRow a=new SSProductRow();a.setProduct("A");a.setDescription("First");a.setQuantity(2);SSProductRow b=new SSProductRow();b.setProduct((String)null);b.setDescription("");b.setQuantity(-1);p.getParcelRows().add(a);p.getParcelRows().add(b);return p;}
 private static Connection conn(String n)throws Exception{Class.forName("org.hsqldb.jdbcDriver");Connection c=DriverManager.getConnection("jdbc:hsqldb:mem:"+n+"_"+UUID.randomUUID(),"sa","");c.setAutoCommit(false);return c;}private static void schema(Connection c)throws Exception{try(InputStream in=ProductRegisterStagingConverterTest.class.getResourceAsStream("/sql/create_tables.sql")){String sql=new String(Objects.requireNonNull(in).readAllBytes(),StandardCharsets.UTF_8);try(var p=c.createStatement()){for(String x:sql.split(";"))if(!x.isBlank())p.execute(x.trim());}c.commit();}}private static void insertCompany(Connection c,SSNewCompany x)throws Exception{try(var p=c.prepareStatement("INSERT INTO tbl_company (id,company) VALUES (?,?)")){p.setInt(1,x.getId());p.setObject(2,x);p.executeUpdate();c.commit();}}private static void insertScoped(Connection c,String t,String col,String key,Object x)throws Exception{try(var p=c.prepareStatement("INSERT INTO "+t+" (number,"+col+",companyid) VALUES (?,?,1)")){p.setString(1,key);p.setObject(2,x);p.executeUpdate();c.commit();}}private static long count(Connection c,String t)throws Exception{try(var p=c.createStatement();var r=p.executeQuery("SELECT COUNT(*) FROM "+t)){r.next();return r.getLong(1);}}
}
